#!/usr/bin/env python3
"""Compact digest of a captured conversation log: human turns, agent prose, tool tally, wall-clock."""
import json, subprocess, sys, datetime

def load(fn):
    raw = subprocess.run(['git','show',f'origin/conversation-logs:{fn}'],
                         capture_output=True, text=True).stdout
    for line in raw.splitlines():
        line=line.strip()
        if not line: continue
        try: yield json.loads(line)
        except Exception: pass

def textof(msg):
    c = msg.get('content')
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if isinstance(b,dict) and b.get('type')=='text': out.append(b.get('text',''))
        return '\n'.join(out)
    return ''

def ts(d):
    t=d.get('timestamp')
    if not t: return None
    try: return datetime.datetime.fromisoformat(t.replace('Z','+00:00'))
    except Exception: return None

for fn in sys.argv[1:]:
    ents=list(load(fn))
    times=[ts(d) for d in ents]; times=[t for t in times if t]
    span=(max(times)-min(times)).total_seconds()/60 if len(times)>1 else 0
    tools={}
    humans=[]; agent=[]
    for d in ents:
        typ=d.get('type')
        if typ=='queue-operation':
            humans.append(('PROMPT', d.get('content','')))
            continue
        m=d.get('message') or {}
        if typ=='user':
            c=m.get('content')
            if isinstance(c,list) and any(isinstance(b,dict) and b.get('type')=='tool_result' for b in c):
                continue
            t=textof(m).strip()
            if t and not t.startswith('<'): humans.append(('USER', t))
        elif typ=='assistant':
            for b in (m.get('content') or []):
                if isinstance(b,dict) and b.get('type')=='tool_use':
                    tools[b.get('name')]=tools.get(b.get('name'),0)+1
            t=textof(m).strip()
            if t: agent.append(t)
    print('='*100)
    print(f'### {fn}')
    print(f'entries={len(ents)} span={span:.1f}min tools={sorted(tools.items(), key=lambda x:-x[1])[:8]}')
    for kind,t in humans[:14]:
        print(f'  [{kind}] {" ".join(t.split())[:700]}')
    print('  --- agent prose (first 2, last 2) ---')
    for t in (agent[:2]+agent[-2:] if len(agent)>4 else agent):
        print(f'  [A] {" ".join(t.split())[:600]}')

